class Solution {
    public int countCells(int[][] grid, int target) {
        int count = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == target) count++;
            }
        }
        return count;
    }
}

